{"file_text": "/* ── Layout ── */
.settings-dashboard {
    display: flex;
    min-height: 80vh;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.25rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #333;
}

.nav-tabs-vertical {
    list-style: none;
    padding: 0;
    margin: 0;
}

.nav-tabs-vertical li {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.65rem 1.25rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
}

.nav-tabs-vertical li:hover {
    background: #e9ecef;
}

.nav-tabs-vertical li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* ── Content ── */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h2 {
    margin: 0 0 0.25rem;
    font-size: 1.5rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.subsection-title {
    margin: 1.5rem 0 0.75rem;
    font-size: 1rem;
    font-weight: 600;
}

/* ── Forms ── */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
}

.form-group .form-control {
    max-width: 480px;
}

.button-row {
    display: flex;
