    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
    max-width: 350px;
}

/* ── Toggle switches ── */
.toggle-row {
    padding: 0.65rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    max-width: 480px;
    font-size: 0.95rem;
}

.toggle-switch {
    width: 40px;
