.confirm-dialog p {
    color: #555;
    margin-bottom: 1.25rem;
}

/* ── Radio group ── */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-bottom: 1rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
