}

/* ── Live preview ── */
.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    max-width: 480px;
    margin-bottom: 0.5rem;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.6rem 1rem;
    font-weight: 600;
