/* Theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-light .preview-header {
    background: #f8f9fa;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-theme-dark .preview-header {
    background: #2a2a3d;
    border-color: #3a3a4d;
