        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ── Loading ── */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
}
