@{
    RenderFragment RenderProfileSection() =>
        @<div class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@_editProfile.AvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="_editProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="_editProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="_editProfile.Bio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                    Discard Changes
                </button>
            </div>
        </div>;
}

@* ───── Notifications ───── *@
@{
    RenderFragment RenderNotificationsSection() =>
        @<div class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-row">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" class="toggle-switch"
                           checked="@_editNotifications!.EmailNotifications"
                           @onchange="e => _editNotifications.EmailNotifications = (bool)e.Value!" />
                </label>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" class="toggle-switch"
                           checked="@_editNotifications.PushNotifications"
                           @onchange="e => _editNotifications.PushNotifications = (bool)e.Value!" />
                </label>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" class="toggle-switch"
                           checked="@_editNotifications.WeeklyDigest"
                           @onchange="e => _editNotifications.WeeklyDigest = (bool)e.Value!" />
                </label>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _editNotifications.MutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Preferences")
                </button>
            </div>
        </div>;
}

@* ───── Security ───── *@
@{
    RenderFragment RenderSecuritySection() =>
        @<div class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Protect your account with passwords and sessions.</p>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control"
                                   @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control"
                                   @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" class="form-control"
                                   @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="field-error">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                            @(_saving ? "Updating…" : "Update Password")
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="toggle-row">
                <label class="toggle-label">
                    <span>
                        Two-Factor Authentication
                        <span class="status-badge @(_securitySettings!.TwoFactorEnabled ? "badge-on" : "badge-off")">
                            @(_securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </span>
                    <input type="checkbox" class="toggle-switch"
                           checked="@_securitySettings.TwoFactorEnabled"
                           @onchange="Toggle2FA" />
                </label>
            </div>

            @if (_securitySettings.LastPasswordChange.HasValue)
            {
                <p class="meta-text">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                </p>
            }

            @* Active Sessions *@
            <h4 class="subsection-title">Active Sessions</h4>
            <div class="table-responsive">
                <table class="table sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrentSession)
                                    {
                                        <span class="current-session-badge">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            @* Revoke confirmation dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="() => _sessionToRevoke = null">
                    <div class="confirm-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@_sessionToRevoke.Device</strong> in
                            <strong>@_sessionToRevoke.Location</strong>?
                        </p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                                @(_saving ? "Revoking…" : "Revoke")
                            </button>
                            <button class="btn btn-outline-secondary"
                                    @onclick="() => _sessionToRevoke = null">
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ───── Appearance ───── *@
@{
    RenderFragment RenderAppearanceSection() =>
        @<div class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <h4 class="subsection-title">Theme</h4>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-option">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_editAppearance!.Theme == theme)"
                               @onchange="() => _editAppearance.Theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>

            <h4 class="subsection-title">Font Size</h4>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_editAppearance.FontSize == size)"
                               @onchange="() => _editAppearance.FontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control"
                        @bind="_editAppearance.Language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <input type="checkbox" class="toggle-switch"
                           checked="@_editAppearance.CompactMode"
                           @onchange="e => _editAppearance.CompactMode = (bool)e.Value!" />
                </label>
            </div>

            @* Live Preview *@
            <h4 class="subsection-title">Preview</h4>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">Dashboard</div>
                <div class="preview-body">
                    <p>This is a preview of your appearance settings.</p>
                    <div class="preview-card">
                        <strong>Sample Card</strong>
                        <span>Some content here to show font size and theme.</span>
                    </div>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </div>;
}

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool _loading = true;
    private bool _saving;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile
    private ProfileEdit? _editProfile;
    private UserProfile? _savedProfile;

    // Notifications
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels = ["announcements", "random", "off-topic", "watercooler"];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceEdit? _editAppearance;

    // Sidebar section definitions
    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["Profile"] = ("Profile", "👤"),
        ["Notifications"] = ("Notifications", "🔔"),
        ["Security"] = ("Security", "🔒"),
        ["Appearance"] = ("Appearance", "🎨"),
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var secTask = SettingsService.GetSecuritySettingsAsync();
        var appearTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, secTask, appearTask);

        _savedProfile = profileTask.Result;
        _editProfile = ProfileEdit.FromProfile(_savedProfile);

        var notifResult = notifTask.Result;
        _editNotifications = new NotificationEdit
        {
            EmailNotifications = notifResult.EmailNotifications,
            PushNotifications = notifResult.PushNotifications,
            WeeklyDigest = notifResult.WeeklyDigest,
            MutedChannels = new List<string>(notifResult.MutedChannels),
        };

        _securitySettings = secTask.Result;

        var appearResult = appearTask.Result;
        _editAppearance = new AppearanceEdit
        {
            Theme = appearResult.Theme,
            FontSize = appearResult.FontSize,
            Language = appearResult.Language,
            CompactMode = appearResult.CompactMode,
        };
    }

    private void SetActiveSection(string section) => ActiveSection = section;

    // ── Toast helper ──
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    // ── Profile ──
    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(
            _editProfile!.DisplayName,
            _editProfile.Email,
            _editProfile.AvatarUrl,
            _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _ = ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            _editProfile = ProfileEdit.FromProfile(_savedProfile);
    }

    // ── Notifications ──
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editNotifications!.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _editNotifications!.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _ = ShowToast("Notification preferences saved.");
    }

    // ── Security ──
    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        _securitySettings = _securitySettings! with { TwoFactorEnabled = enabled };
        StateHasChanged();
        await Task.CompletedTask;
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;
        if (string.IsNullOrWhiteSpace(_currentPassword)
            || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }
        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _saving = false;
        _passwordPanelOpen = false;
        _ = ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session) =>
        _sessionToRevoke = session;

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        _saving = false;
        _ = ShowToast("Session revoked.");
    }

    // ── Appearance ──
    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance!.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(
            _editAppearance!.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _ = ShowToast("Appearance settings saved.");
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Mutable edit models ──
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static ProfileEdit FromProfile(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio,
        };
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }
}

