/* ── Layout ── */
.settings-dashboard {
    display: flex;
    min-height: 80vh;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.25rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #333;
}

.nav-tabs-vertical {
    list-style: none;
    padding: 0;
    margin: 0;
}

.nav-tabs-vertical li {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.65rem 1.25rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
}

.nav-tabs-vertical li:hover {
    background: #e9ecef;
}

.nav-tabs-vertical li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* ── Content ── */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h2 {
    margin: 0 0 0.25rem;
    font-size: 1.5rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.subsection-title {
    margin: 1.5rem 0 0.75rem;
    font-size: 1rem;
    font-weight: 600;
}

/* ── Forms ── */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
}

.form-group .form-control {
    max-width: 480px;
}

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.field-error {
    color: #dc3545;
    font-size: 0.875rem;
    margin-bottom: 0.75rem;
}

/* ── Avatar ── */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
    max-width: 350px;
}

/* ── Toggle switches ── */
.toggle-row {
    padding: 0.65rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    max-width: 480px;
    font-size: 0.95rem;
}

.toggle-switch {
    width: 40px;
    height: 22px;
    accent-color: #0d6efd;
    cursor: pointer;
    appearance: auto;
}

/* ── Channels ── */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    max-width: 480px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.35rem 0.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f8f9fa;
}

/* ── Expandable panel ── */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-chevron {
    transition: transform 0.2s;
    display: inline-block;
}

.panel-chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* ── Status badges ── */
.status-badge {
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    margin-left: 0.5rem;
    font-weight: 600;
}

.badge-on {
    background: #d1e7dd;
    color: #0f5132;
}

.badge-off {
    background: #f8d7da;
    color: #842029;
}

.current-session-badge {
    font-size: 0.8rem;
    color: #0d6efd;
    font-weight: 500;
}

